import java.util.Scanner;

public class Main {

    public void solve() {
        Scanner sc = new Scanner(System.in);
        long base = sc.nextLong();
        long target = sc.nextLong();
        int powerLevel = 0;
        while (Math.pow(base, powerLevel) < target) {
            powerLevel++;
        }
        if (Math.pow(base, powerLevel) == target) {
            System.out.println("YES");
            return;
        }

        long maxPowerValue = (long) Math.pow(base, powerLevel);
        long sumSeries = (maxPowerValue - 1) / (base - 1);
        if (maxPowerValue - sumSeries == target) {
            System.out.println("YES");
            return;
        }
        if (checkDivisibilityPath(base, target)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    private boolean checkDivisibilityPath(long base, long target) {
        if (target == 1) {
            return true;
        }
        if (target % base == 0) {
            return checkDivisibilityPath(base, target / base);
        } else if ((target - 1) % base == 0) {
            return checkDivisibilityPath(base, (target - 1) / base);
        } else if ((target + 1) % base == 0) {
            return checkDivisibilityPath(base, (target + 1) / base);
        }
        return false;
    }

    public static void main(String[] args) {
        new Main().solve();
    }
}
